BEGIN TRANSACTION;
CREATE TABLE bets (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    match_url TEXT UNIQUE NOT NULL,
                    detected_at TEXT NOT NULL,
                    tournament TEXT,
                    surface TEXT,
                    player_a TEXT,
                    player_b TEXT,
                    selected_player TEXT,
                    book_odds REAL,
                    model_odds REAL,
                    model_prob REAL,
                    ev_percent REAL,
                    elo_diff REAL,
                    kelly_stake_pct REAL DEFAULT 0.0,
                    status TEXT DEFAULT 'En attente',
                    winner TEXT DEFAULT '',
                    profit_units REAL DEFAULT 0.0
                , closing_odds REAL DEFAULT 0.0, clv_percent REAL DEFAULT 0.0);
CREATE TABLE matches (
                    match_url TEXT PRIMARY KEY,
                    analyzed_at TEXT NOT NULL,
                    tournament TEXT,
                    surface TEXT,
                    player_a TEXT,
                    player_b TEXT,
                    model_odds_a REAL,
                    model_odds_b REAL,
                    book_odds_a REAL,
                    book_odds_b REAL,
                    elo_a REAL,
                    elo_b REAL,
                    confidence_index REAL,
                    summary_line TEXT
                );
DELETE FROM "sqlite_sequence";
COMMIT;
